contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 depAmount, uint256 wAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depAmount)); require(depAmount <= 1000000000000000000000000000000);
        require(depAmount > 0);
        require(msg.sender != address(0));
        require(address(this).balance >= depAmount);

        c.deposit{value: depAmount}(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdraw(wAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        assert(reverted == (wAmount > depAmount));
    }

    receive() external payable {}
}

