// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(uint256 depAmount, uint256 wAmount) internal {
        depAmount = bound(depAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(depAmount > 0);
        vm.assume(msg.sender != address(0));
        vm.assume(address(this).balance >= depAmount);
        try c.deposit{value: depAmount}() {} catch { return; }
        bool reverted;
        try c.withdraw(wAmount) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted == (wAmount > depAmount));
    }

    function testFuzz_run(uint256 depAmount, uint256 wAmount) public {
        _run(depAmount, wAmount);
    }

    receive() external payable {}
}
